INSERT INTO public.gk_facts (book_id,chapter_id,topic_id,title,fact_text,explanation,source_page,source_section,source_excerpt,importance,confidence,canonical_hash) SELECT b.id,c.id,t.id,'Leonardo da Vinci — Mona Lisa','লিওনার্দো দা ভিঞ্চির উল্লেখযোগ্য চিত্রকর্ম ‘মোনালিসা’।','Exact source artwork-attribution was visually reviewed, OCR-reconciled, and directly authority-verified; citations are recorded in the batch verification ledger.',855,'Leonardo da Vinci — Mona Lisa','লিওনার্দো দা ভিঞ্চির উল্লেখযোগ্য চিত্রকর্ম ‘মোনালিসা’।',3,'high'::confidence_level,'5ce0e3e4b0aa11fa3953959e66da19e9d2876728d970083e394905045186b006' FROM public.books b JOIN public.chapters c ON c.book_id=b.id AND c.slug='europe' JOIN public.topics t ON t.chapter_id=c.id AND t.slug='leonardo-art-reference-boundary-855' WHERE b.title='Jubayer''s GK' ON CONFLICT (canonical_hash) DO UPDATE SET fact_text=EXCLUDED.fact_text,explanation=EXCLUDED.explanation,confidence=EXCLUDED.confidence;
