INSERT INTO public.flashcards (subject_id,book_id,chapter_id,topic_id,front_text,back_text,source_type,source_id,source_key) SELECT (SELECT id FROM public.subjects ORDER BY created_at ASC LIMIT 1),f.book_id,f.chapter_id,f.topic_id,f.title,f.fact_text,'fact',f.id,'batch0854-0858:fact:'||f.id::text FROM public.gk_facts f WHERE f.source_page BETWEEN 854 AND 858 AND NOT EXISTS (SELECT 1 FROM public.flashcards z WHERE z.source_key='batch0854-0858:fact:'||f.id::text);
INSERT INTO public.search_documents (entity_type,entity_id,title,body,english_metadata) SELECT 'fact',f.id,f.title,f.fact_text,'Verified artwork attribution | source page '||f.source_page::text FROM public.gk_facts f WHERE f.source_page BETWEEN 854 AND 858 AND NOT EXISTS (SELECT 1 FROM public.search_documents d WHERE d.entity_type='fact' AND d.entity_id=f.id);
